<x-layouts.app :title="$worker->name">
    <a class="back-link" href="/">← Back to people</a>
    <div class="profile-heading"><span class="avatar large lilac">{{ $worker->initials() }}</span><div><span class="badge {{ $worker->status }}">{{ ucfirst($worker->status) }}</span><h1>{{ $worker->name }}</h1><p class="subtle">{{ $worker->title }} <span class="meta-divider">·</span> {{ $worker->team }} <span class="meta-divider">·</span> {{ $worker->location }}</p></div><span class="version-label">Record version {{ $worker->version }}</span></div>
    <ol class="lifecycle" aria-label="Lifecycle progress">@foreach(\App\Models\Worker::STATUSES as $state)<li @class(['current' => $worker->status === $state, 'done' => array_search($state, \App\Models\Worker::STATUSES) < array_search($worker->status, \App\Models\Worker::STATUSES)]) @if($worker->status === $state) aria-current="step" @endif><span>{{ $loop->iteration }}</span>{{ ucfirst($state) }}</li>@endforeach</ol>
    <div class="detail-grid"><div>
        <section class="panel"><div class="panel-heading"><div><span class="eyebrow">SMALL STEPS, SMOOTH TRANSITIONS</span><h2>Journey checklist</h2></div><span class="panel-icon" aria-hidden="true">☷</span></div>@foreach(['onboarding' => 'Onboarding', 'offboarding' => 'Offboarding'] as $phase => $label)<div class="task-phase"><div class="task-phase-title"><h3>{{ $label }}</h3><span>{{ $worker->tasks->where('phase', $phase)->whereNotNull('completed_at')->count() }}/{{ $worker->tasks->where('phase', $phase)->count() }} complete</span></div>@foreach($worker->tasks->where('phase', $phase) as $task)<div class="task-row" data-testid="task-{{ $task->id }}"><span @class(['task-check', 'checked' => $task->completed_at]) aria-hidden="true">{{ $task->completed_at ? '✓' : '' }}</span><div><strong>{{ $task->name }}</strong><small>{{ $task->completed_at ? 'Completed '.$task->completed_at->format('M j, Y') : 'Required before '.($phase === 'onboarding' ? 'activation' : 'closure') }}</small></div>@if(!$task->completed_at && $worker->status === $phase && auth()->user()->canManage())<form method="post" action="{{ route('workers.complete', [$worker->id, $task->id]) }}">@csrf<input type="hidden" name="version" value="{{ $worker->version }}"><button class="button small secondary" aria-label="Complete {{ $task->name }}">Complete</button></form>@endif</div>@endforeach</div>@endforeach</section>
        <section class="panel equipment-panel"><div class="panel-heading"><div><span class="eyebrow">THE TOOLS TO DO GREAT WORK</span><h2>Assigned equipment</h2></div><span class="small-count">{{ $worker->equipment->count() }}</span></div>@forelse($worker->equipment as $asset)<div class="asset-row"><span class="equipment-icon" aria-hidden="true">▣</span><div><strong>{{ $asset->name }}</strong><small>{{ $asset->code }} · {{ $asset->category }}</small></div>@if(auth()->user()->canManage())<form method="post" action="{{ route('workers.return', [$worker->id, $asset->id]) }}">@csrf<input type="hidden" name="version" value="{{ $worker->version }}"><button class="button small secondary" aria-label="Return {{ $asset->code }}">Return</button></form>@endif</div>@empty<p class="empty-inline">No equipment assigned. A clean slate.</p>@endforelse @if(auth()->user()->canManage() && in_array($worker->status, ['onboarding', 'active']))<form class="assign-form" method="post" action="{{ route('workers.assign', $worker->id) }}">@csrf<input type="hidden" name="version" value="{{ $worker->version }}"><div><label for="asset_id">Available equipment</label><select id="asset_id" name="asset_id" required><option value="">Choose an item</option>@foreach($available as $asset)<option value="{{ $asset->id }}">{{ $asset->code }} · {{ $asset->name }}</option>@endforeach</select></div><button class="button secondary" @disabled($available->isEmpty())>Assign equipment</button></form>@endif</section>
    </div><aside class="detail-aside"><section class="panel next-step"><span class="eyebrow">WHAT COMES NEXT</span><h2>{{ ['draft' => 'Ready for a good start?', 'onboarding' => 'Make room to begin.', 'active' => 'Keep good work moving.', 'offboarding' => 'Leave things in good hands.', 'closed' => 'A journey, wrapped up.'][$worker->status] }}</h2><p>{{ ['draft' => 'Start onboarding to unlock the welcome checklist and equipment allocation.', 'onboarding' => 'Complete both required onboarding tasks before activating this person.', 'active' => 'When it is time to move on, start offboarding to open the handover checklist.', 'offboarding' => 'Complete the handover checklist and return every assigned item before closing.', 'closed' => 'This record is closed. Its journey and activity history remain available.'][$worker->status] }}</p>@if(auth()->user()->canManage() && $worker->status !== 'closed')<form method="post" action="{{ route('workers.transition', $worker->id) }}">@csrf<input type="hidden" name="version" value="{{ $worker->version }}"><input type="hidden" name="status" value="{{ ['draft' => 'onboarding', 'onboarding' => 'active', 'active' => 'offboarding', 'offboarding' => 'closed'][$worker->status] }}"><button class="button primary wide">{{ ['draft' => 'Start onboarding', 'onboarding' => 'Activate worker', 'active' => 'Begin offboarding', 'offboarding' => 'Close worker'][$worker->status] }} <span aria-hidden="true">→</span></button></form>@elseif(!auth()->user()->canManage())<p class="viewer-note">Viewer access · Ask an administrator to make changes.</p>@endif</section><section class="panel history-panel"><div class="panel-heading"><h2>Recent activity</h2><span aria-hidden="true">◷</span></div><ol class="timeline">@foreach($worker->events->sortByDesc('id')->take(8) as $event)<li><span class="timeline-dot"></span><strong>{{ str_replace('_', ' ', ucfirst($event->action)) }}</strong><p>{{ $event->detail }}</p><small>{{ $event->actor->name }} · {{ $event->created_at->format('M j, H:i') }} UTC</small></li>@endforeach</ol></section></aside></div>
</x-layouts.app>
